const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');

const initial = () => ({ displayName: 'before', tags: ['old'] });
const service = (profile = initial()) => new ProfileService(profile);

function rejects(input, profile = initial()) {
  const svc = service(profile);
  const before = JSON.parse(JSON.stringify(svc.profile));
  let error = null;
  try {
    svc.patch(input);
  } catch (caught) {
    error = caught;
  }
  assert.ok(error instanceof Error, `expected Error for ${String(input)}`);
  assert.equal(error.message, 'invalid profile');
  assert.deepEqual(svc.profile, before, 'storage changed after invalid patch');
}

// Empty object is a no-op.
{
  const profile = initial();
  const svc = service(profile);
  assert.deepEqual(svc.patch({}), { displayName: 'before', tags: ['old'] });
  assert.deepEqual(profile, { displayName: 'before', tags: ['old'] });
}

// displayName: keep / trim / clear.
{
  const svc = service();
  assert.deepEqual(svc.patch({ displayName: '  after  ' }), { displayName: 'after', tags: ['old'] });
  assert.deepEqual(svc.patch({ displayName: null }), { displayName: null, tags: ['old'] });
  assert.deepEqual(svc.patch({ tags: ['new'] }), { displayName: null, tags: ['new'] });
}

// displayName bounds.
{
  const svc = service();
  assert.equal(svc.patch({ displayName: 'a'.repeat(40) }).displayName, 'a'.repeat(40));
  assert.equal(svc.patch({ displayName: '  ' + 'b'.repeat(40) + '  ' }).displayName, 'b'.repeat(40));
}
rejects({ displayName: '' });
rejects({ displayName: '   ' });
rejects({ displayName: 'a'.repeat(41) });
rejects({ displayName: 'a'.repeat(41) + '  ' });
rejects({ displayName: undefined });
rejects({ displayName: 5 });
rejects({ displayName: true });
rejects({ displayName: new String('x') });
rejects({ displayName: ['name'] });

// tags: trim, dedupe after trim, bounds, clear.
{
  const svc = service();
  assert.deepEqual(svc.patch({ tags: [' a ', 'b'] }).tags, ['a', 'b']);
  assert.equal(svc.patch({ tags: ['c'.repeat(12)] }).tags[0], 'c'.repeat(12));
  assert.deepEqual(svc.patch({ tags: ['  ' + 'd'.repeat(12) + ' '] }).tags, ['d'.repeat(12)]);
  assert.deepEqual(svc.patch({ tags: null }).tags, []);
  const svc2 = service();
  assert.deepEqual(svc2.patch({ tags: [] }).tags, []);
  assert.deepEqual(svc2.patch({ tags: ['x'] }), { displayName: 'before', tags: ['x'] });
  const five = service();
  assert.deepEqual(five.patch({ tags: ['a', 'b', 'c', 'd', 'e'] }).tags, ['a', 'b', 'c', 'd', 'e']);
}
rejects({ tags: [' a ', 'a'] });
rejects({ tags: ['a', ' a'] });
rejects({ tags: [''] });
rejects({ tags: ['   '] });
rejects({ tags: ['c'.repeat(13)] });
rejects({ tags: ['c'.repeat(13) + '  '] });
rejects({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] });
rejects({ tags: [1] });
rejects({ tags: ['a', 2] });
rejects({ tags: [null] });
rejects({ tags: [undefined] });
rejects({ tags: 'a,b' });
rejects({ tags: { 0: 'a' } });
rejects({ tags: true });
rejects({ tags: 5 });

// A patch that mixes valid and invalid fields leaves storage unchanged.
rejects({ displayName: 'new', tags: [''] });
rejects({ displayName: 1, tags: ['ok'] });

// Both fields can be cleared in one patch.
{
  const svc = service();
  assert.deepEqual(svc.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
}

// Unknown keys.
rejects({ extra: true });
rejects({ displayName: 'ok', extra: true });
rejects({ tags: ['ok'], extra: true });
rejects({ [Symbol('extra')]: 1 });

// Shapes.
rejects(null);
rejects(undefined);
rejects(42);
rejects('string');
rejects(true);
rejects([]);
rejects(['displayName']);
rejects(new Date());
class Custom { constructor() { this.displayName = 'x'; this.tags = []; } }
rejects(new Custom());
rejects(Object.create({}));
rejects(Object.create({ displayName: 'inherited', tags: [] }));

// Null-prototype plain objects are accepted.
{
  const input = Object.create(null);
  input.displayName = ' null proto ';
  input.tags = [' t '];
  const svc = service();
  assert.deepEqual(svc.patch(input), { displayName: 'null proto', tags: ['t'] });
}

// Input is not mutated, and caller arrays are not reused for storage.
{
  const input = { displayName: '  x  ', tags: [' a '] };
  const inputSnapshot = { displayName: input.displayName, tags: input.tags.slice() };
  const svc = service();
  const result = svc.patch(input);
  assert.deepEqual(input, inputSnapshot);
  assert.notEqual(result.tags, input.tags);
  input.tags.push('mutated');
  input.displayName = 'mutated';
  assert.deepEqual(svc.profile, { displayName: 'x', tags: ['a'] });
  assert.deepEqual(result, { displayName: 'x', tags: ['a'] });
}

console.log('contract checks passed');

